<link rel="stylesheet" href="/assets/reports.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/reports.css'))?>">
<div class="report-heading"><div><p class="report-eyebrow">REKAP ANTREAN</p><h1>Laporan layanan</h1><p><?=e($periodLabel)?></p></div><a class="button secondary" href="?<?=e(http_build_query(array_merge($_GET,['format'=>'csv'])))?>">Unduh CSV</a></div>
<form class="report-filter" method="get"><label>Jenis rekap<select name="period" id="report-period"><option value="daily" <?=$period==='daily'?'selected':''?>>Harian</option><option value="monthly" <?=$period==='monthly'?'selected':''?>>Bulanan</option><option value="range" <?=$period==='range'?'selected':''?>>Rentang tanggal</option></select></label><label class="period-field" data-period="daily">Tanggal<input type="date" name="date" value="<?=e($selectedDate)?>"></label><label class="period-field" data-period="monthly">Bulan<input type="month" name="month" value="<?=e($selectedMonth)?>"></label><label class="period-field" data-period="range">Dari<input type="date" name="from" value="<?=e($dateFrom)?>"></label><label class="period-field" data-period="range">Sampai<input type="date" name="to" value="<?=e($dateTo)?>"></label><button type="submit">Tampilkan</button></form>
<section class="report-stats"><article><span>Total tiket</span><b><?=e($summary['total'])?></b></article><article><span>Menunggu</span><b><?=e($summary['waiting'])?></b></article><article><span>Sedang aktif</span><b><?=e($summary['active'])?></b></article><article><span>Selesai</span><b><?=e($summary['completed'])?></b></article></section>
<section class="report-table-card"><div class="report-table-title"><div><h2>Rincian berdasarkan tanggal</h2><p><?=e($start)?> sampai <?=e($end)?></p></div><span><?=e(count($rows))?> baris</span></div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Tanggal</th><th>Layanan</th><th>Sublayanan</th><th>Total</th><th>Menunggu</th><th>Aktif</th><th>Selesai</th><th>Dilewati</th><th>Dibatalkan</th><th>Rata-rata</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10" class="report-empty">Belum ada data antrean pada periode ini.</td></tr><?php else:foreach($rows as $r):?><tr><td><b><?=e((new DateTimeImmutable($r['queue_date']))->format('d/m/Y'))?></b></td><td><?=e($r['service_name'])?></td><td><?=e($r['sub_service_name']??'—')?></td><td><b><?=e($r['total'])?></b></td><td><?=e($r['waiting'])?></td><td><?=e($r['active'])?></td><td><span class="report-complete"><?=e($r['completed'])?></span></td><td><?=e($r['skipped'])?></td><td><?=e($r['cancelled'])?></td><td><?=e($r['avg_minutes']??'-')?><?=isset($r['avg_minutes'])?' menit':''?></td></tr><?php endforeach;endif?></tbody></table></div></section>
<script>const period=document.querySelector('#report-period'),syncPeriod=()=>document.querySelectorAll('.period-field').forEach(field=>field.hidden=field.dataset.period!==period.value);period.addEventListener('change',syncPeriod);syncPeriod();</script>
